import { strict as assert } from "node:assert";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { aggregatePlaytestAnalytics, playtestCardActivityCsv } from "../src/playtest-analytics.js";
import { RoomService } from "../src/room.js";
let passed = 0;
const root = (n) => readFileSync(fileURLToPath(new URL(`../../${n}`, import.meta.url)), "utf8");
const pkg = JSON.parse(root("package.json")), server = root("server/server.mjs"), html = root("public/index.html"), app = root("public/app.js"), css = root("public/styles.css"), roomSrc = root("src/room.ts");
function test(n, f) { f(); passed++; console.log(`✓ ${n}`); }
function endedRecord() { let n = 0; const rooms = new RoomService({ roomIdFactory: () => "HUM766", tokenFactory: () => `h-${++n}`, firstPlayerFactory: () => "P1", nowFactory: () => 1000 }); const h = rooms.createRoom("customer-service-starter"); const g = rooms.joinRoom(h.roomId, "it-starter"); rooms.submitIntent(h.roomId, g.token, { intentId: "r", expectedStateVersion: rooms.getView(h.roomId, g.token, 0).match.stateVersion, intent: { type: "RESIGN" } }); return rooms.listPlaytestRecords()[0]; }
test("v7.66 version markers are current", () => { assert.equal(pkg.version, "7.66.0"); assert.match(server, /7\.66\.0/); assert.match(html, /v7\.66 Alpha Playtest/); });
test("room records derive anonymous card activity from authoritative events", () => { assert.match(roomSrc, /playtestCardActivity/); assert.match(roomSrc, /state\.eventLog/); assert.match(roomSrc, /CARD_DRAWN/); assert.match(roomSrc, /CARD_PLAYED/); assert.match(roomSrc, /ATTACK_DECLARED/); assert.ok(Array.isArray(endedRecord().cardActivity)); });
test("analytics reports deck opener split card use resigns and friction", () => { const r = endedRecord(); r.cardActivity = [{ definitionId: "CS-001", name: "Customer Service Agent", department: "CUSTOMER_SERVICE", playerId: "P1", observedInstances: 1, playedInstances: 1, draws: 1, plays: 1, activations: 0, attacks: 0 }]; const a = aggregatePlaytestAnalytics([r], 2000); const d = a.decks.find(x => x.deckId === r.seats.P1.deckId); assert.equal(d.firstAppearances, 1); assert.equal(d.firstWinRate, 100); assert.equal(a.cards[0].winRateWhenPlayed, 100); assert.equal(a.totals.resigns, 1); assert.ok(a.friction.thresholds.longTurnSeconds > 0); });
test("card CSV export exposes activity fields without player identity", () => { const csv = playtestCardActivityCsv([{ definitionId: "CS-001", name: "Agent", department: "CUSTOMER_SERVICE", observedSeatMatches: 2, playedSeatMatches: 1, observedInstances: 2, playedInstances: 1, draws: 1, plays: 1, activations: 0, attacks: 0, winsWhenPlayed: 1, lossesWhenPlayed: 0, drawsWhenPlayed: 0, winRateWhenPlayed: 100, playRateFromObserved: 50 }]); assert.match(csv, /definitionId,name,department/); assert.match(csv, /winRateWhenPlayed/); assert.doesNotMatch(csv, /profile|token|playerId/); });
test("admin analytics use header auth and protected fetch exports", () => { assert.match(app, /playtest\/analytics.*headers:adminAuthHeaders/); assert.match(app, /function exportPlaytestAnalytics/); assert.match(app, /data-analytics-export="cards-csv"/); assert.match(server, /format === "cards-csv"/); });
test("human signal UI explicitly remains directional instead of auto-balancing", () => { assert.match(app, /Human match signals/); assert.match(app, /No automatic balance changes/); assert.match(css, /v7\.66 — human playtest signal readout/); });
console.log(`${passed}/6 v7.66 tests passed.`);
